window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b2ed35b170cd4f4b"]={"versions": [{"id": "FIG-b2ed35b170cd4f4b", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Blocklayout-Diagramm zur physischen Speicheraufteilung im NVRAM Manager (NvM) der AUTOSAR Classic Platform. Das Diagramm spezifiziert die interne Datenstruktur eines redundanten NVRAM-Blocks (NVRAM block management type: Redundant) innerhalb des nichtflüchtigen Speichers (NV memory).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei identisch aufgebaute NV-Blöcke (NV Block 1 und NV Block 2) im NV-Speicher dar:</p>\n<ul class=\"fig-list\"><li><strong>NV block data</strong>: Nutzdatenbereich des jeweiligen NV-Blocks.\n</li><li><strong>NV block CRC (optional)</strong>: Optionales Prüfsummenfeld direkt anschließend an den Nutzdatenbereich zur Integritätsabsicherung des jeweiligen NV-Blocks.\n</li></ul>\n<p class=\"fig-p\">Beide Blöcke bilden gemeinsam das redundante Blockpaar für die Speicherung derselben logischen Daten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamischen Ablauf. Beim Schreib- und Lesezugriff durch den NvM werden beide Blöcke verwaltet:</p>\n<ul class=\"fig-list\"><li>Beim Lesen wird primär der erste Block herangezogen und über die optionale CRC verifiziert; bei einem CRC- oder Zugriffsfehler wird auf den zweiten Block zurückgegriffen.\n</li><li>Bei Schreiboperationen werden beide NV-Blöcke sequenziell mit den aktuellen Anwendungsdaten sowie der neu berechneten CRC aktualisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Speicherlayout eines redundanten NVRAM-Blocks im NvM:</p>\n<ul class=\"fig-list\"><li>Ein redundanter NVRAM-Block besteht im NV-Speicher aus genau zwei physischen NV-Blöcken.\n</li><li>Jeder NV-Block enthält den Nutzdatenbereich (NV block data) und optional das nachgestellte Prüfsummenfeld (NV block CRC).\n</li><li>Die Konfiguration der CRC (vorhanden/nicht vorhanden) gilt einheitlich für beide redundanten Instanzen des Blocks.\n</li></ul>"}, {"id": "FIG-ceff2a088c12fc8a", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Blocklayout-Diagramm zur physischen Speicheraufteilung im NVRAM Manager (NvM) der AUTOSAR Classic Platform. Das Diagramm spezifiziert die interne Datenstruktur eines redundanten NVRAM-Blocks (NVRAM block management type: Redundant) innerhalb des nichtflüchtigen Speichers (NV memory).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei identisch aufgebaute NV-Blöcke (NV Block 1 und NV Block 2) im NV-Speicher dar:</p>\n<ul class=\"fig-list\"><li><strong>NV block data</strong>: Nutzdatenbereich des jeweiligen NV-Blocks.\n</li><li><strong>NV block CRC (optional)</strong>: Optionales Prüfsummenfeld direkt anschließend an den Nutzdatenbereich zur Integritätsabsicherung des jeweiligen NV-Blocks.\n</li></ul>\n<p class=\"fig-p\">Beide Blöcke bilden gemeinsam das redundante Blockpaar für die Speicherung derselben logischen Daten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamischen Ablauf. Beim Schreib- und Lesezugriff durch den NvM werden beide Blöcke verwaltet:</p>\n<ul class=\"fig-list\"><li>Beim Lesen wird primär der erste Block herangezogen und über die optionale CRC verifiziert; bei einem CRC- oder Zugriffsfehler wird auf den zweiten Block zurückgegriffen.\n</li><li>Bei Schreiboperationen werden beide NV-Blöcke sequenziell mit den aktuellen Anwendungsdaten sowie der neu berechneten CRC aktualisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Speicherlayout eines redundanten NVRAM-Blocks im NvM:</p>\n<ul class=\"fig-list\"><li>Ein redundanter NVRAM-Block besteht im NV-Speicher aus genau zwei physischen NV-Blöcken.\n</li><li>Jeder NV-Block enthält den Nutzdatenbereich (NV block data) und optional das nachgestellte Prüfsummenfeld (NV block CRC).\n</li><li>Die Konfiguration der CRC (vorhanden/nicht vorhanden) gilt einheitlich für beide redundanten Instanzen des Blocks.\n</li></ul>"}, {"id": "FIG-686ff5c77dcf4299", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Blocklayout-Diagramm zur physischen Speicheraufteilung im NVRAM Manager (NvM) der AUTOSAR Classic Platform. Das Diagramm spezifiziert die interne Datenstruktur eines redundanten NVRAM-Blocks (NVRAM block management type: Redundant) innerhalb des nichtflüchtigen Speichers (NV memory).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei identisch aufgebaute NV-Blöcke (NV Block 1 und NV Block 2) im NV-Speicher dar:</p>\n<ul class=\"fig-list\"><li><strong>NV block data</strong>: Nutzdatenbereich des jeweiligen NV-Blocks.\n</li><li><strong>NV block CRC (optional)</strong>: Optionales Prüfsummenfeld direkt anschließend an den Nutzdatenbereich zur Integritätsabsicherung des jeweiligen NV-Blocks.\n</li></ul>\n<p class=\"fig-p\">Beide Blöcke bilden gemeinsam das redundante Blockpaar für die Speicherung derselben logischen Daten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamischen Ablauf. Beim Schreib- und Lesezugriff durch den NvM werden beide Blöcke verwaltet:</p>\n<ul class=\"fig-list\"><li>Beim Lesen wird primär der erste Block herangezogen und über die optionale CRC verifiziert; bei einem CRC- oder Zugriffsfehler wird auf den zweiten Block zurückgegriffen.\n</li><li>Bei Schreiboperationen werden beide NV-Blöcke sequenziell mit den aktuellen Anwendungsdaten sowie der neu berechneten CRC aktualisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Speicherlayout eines redundanten NVRAM-Blocks im NvM:</p>\n<ul class=\"fig-list\"><li>Ein redundanter NVRAM-Block besteht im NV-Speicher aus genau zwei physischen NV-Blöcken.\n</li><li>Jeder NV-Block enthält den Nutzdatenbereich (NV block data) und optional das nachgestellte Prüfsummenfeld (NV block CRC).\n</li><li>Die Konfiguration der CRC (vorhanden/nicht vorhanden) gilt einheitlich für beide redundanten Instanzen des Blocks.\n</li></ul>"}, {"id": "FIG-bc6eef02ac5f9db2", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Blocklayout-Diagramm zur physischen Speicheraufteilung im NVRAM Manager (NvM) der AUTOSAR Classic Platform. Das Diagramm spezifiziert die interne Datenstruktur eines redundanten NVRAM-Blocks (NVRAM block management type: Redundant) innerhalb des nichtflüchtigen Speichers (NV memory).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei identisch aufgebaute NV-Blöcke (NV Block 1 und NV Block 2) im NV-Speicher dar:</p>\n<ul class=\"fig-list\"><li><strong>NV block data</strong>: Nutzdatenbereich des jeweiligen NV-Blocks.\n</li><li><strong>NV block CRC (optional)</strong>: Optionales Prüfsummenfeld direkt anschließend an den Nutzdatenbereich zur Integritätsabsicherung des jeweiligen NV-Blocks.\n</li></ul>\n<p class=\"fig-p\">Beide Blöcke bilden gemeinsam das redundante Blockpaar für die Speicherung derselben logischen Daten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamischen Ablauf. Beim Schreib- und Lesezugriff durch den NvM werden beide Blöcke verwaltet:</p>\n<ul class=\"fig-list\"><li>Beim Lesen wird primär der erste Block herangezogen und über die optionale CRC verifiziert; bei einem CRC- oder Zugriffsfehler wird auf den zweiten Block zurückgegriffen.\n</li><li>Bei Schreiboperationen werden beide NV-Blöcke sequenziell mit den aktuellen Anwendungsdaten sowie der neu berechneten CRC aktualisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Speicherlayout eines redundanten NVRAM-Blocks im NvM:</p>\n<ul class=\"fig-list\"><li>Ein redundanter NVRAM-Block besteht im NV-Speicher aus genau zwei physischen NV-Blöcken.\n</li><li>Jeder NV-Block enthält den Nutzdatenbereich (NV block data) und optional das nachgestellte Prüfsummenfeld (NV block CRC).\n</li><li>Die Konfiguration der CRC (vorhanden/nicht vorhanden) gilt einheitlich für beide redundanten Instanzen des Blocks.\n</li></ul>"}], "trans": [{"from": "FIG-b2ed35b170cd4f4b", "to": "FIG-ceff2a088c12fc8a", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ceff2a088c12fc8a", "to": "FIG-686ff5c77dcf4299", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-686ff5c77dcf4299", "to": "FIG-bc6eef02ac5f9db2", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
